  <table id="json-table"></table>

  <script>
    const jsonFile = 'path/to/your/json/file.json'; // replace with your json file path
    const jsonData = fetch(jsonFile)
      .then(response => response.json())
      .then(data => {
        const tableHTML = '<tr><th>' + Object.keys(data[0]).join('</th><th>') + '</th></tr>';
        data.forEach(item => {
          tableHTML += '<tr><td>' + Object.values(item).map(value => `<code>${markdownify(value)}</code>`).join('</td><td>') + '</td></tr>';
        });
        document.getElementById('json-table').innerHTML = tableHTML;
      })
      .catch(error => console.error(error));

    function markdownify(text) {
      return text.replace(/[*_]/g, match => {
        switch (match) {
          case '*':
            return '<em>';
          case '_':
            return '<i>';
        }
      }).replace(/`([^`]*)`/g, '<code>$1</code>');
    }
  </script>
</body>
</html>
```
