Here is a P5.js sketch that generates a beautiful red heart as a fractal using Perlin noise:
```javascript
//(set up variables)
var angle = 0;
var heartScale = 100;
var heartOffset = 0;

//set up canvas
function setup() {
  createCanvas(500, 500, WEBGL);
}

//draw the heart fractal
function draw() {
  //clear the canvas
  background(0);

  //translate to the center of the canvas
  translate(width / 2, height / 2);

  //rotate around the Z-axis
  rotateZ(angle);

  //create the heart shape
  fill(255, 0, 0); //red
  noStroke();

  //draw the heart shape fractally
  drawHeart(0, 0, heartScale, heartOffset);

  //advance the angle and offset
  angle += 0.01;
  heartOffset += 0.01;
}

//draw the heart shape fractally
function drawHeart(x, y, scale, offset) {
  //base case: if the scale is too small, just draw a circle
  if (scale < 5) {
    ellipse(x, y, scale, scale);
    return;
  }

  //generate the heart shape using Perlin noise
  var points = [];
  for (var i = 0; i < 360; i += 10) {
    var theta = radians(i);
    var r = lerp(0, scale, noise(x + offset + theta, y + offset));
    points.push(createVector(r * cos(theta), r * sin(theta)));
  }

  //close the shape by connecting the last point to the first
  points.push(points[0]);

  //draw the shape
  beginShape();
  for (var i = 0; i < points.length; i++) {
    vertex(points[i].x, points[i].y);
  }
  endShape(CLOSE);

  //recursively draw the heart shape at smaller scales
  for (var i = 0; i < points.length; i++) {
    var newScale = scale * 0.7;
    var newX = points[i].x;
    var newY = points[i].y;
    drawHeart(newX, newY, newScale, offset + i / 360);
  }
}
```
This sketch uses the `noise()` function from P5.js to generate Perlin noise values, which are then used to determine the radius of the heart shape at each point. The `drawHeart()` function recursively calls itself to draw the heart shape at smaller scales, creating a fractal effect.

